import collections,json
from pathlib import Path
out=Path(__file__).resolve().parent
read=lambda n:json.loads((out/n).read_text())
p=read('provenance.json');groups=read('grouped-first-stops.json');comparison=read('comparison.json');art=read('root-order.json');totals=read('latent-totals.json');excerpts=read('source-excerpts.json')
checks={r['root']:r for r in art['checks']}
q=lambda x:'`'+str(x)+'`'
lines=['# Next stops on main 93e8aff54','','Measured for task baobab. Report only.','',f'Compiler and apply SHA: {q(p["sha"])}. TypeScript 6.0.3 source pin: {q(p["typescript_pin"])}.','',f'Box: {q(p["box"])}; {p["cpus"]} visible CPUs; CPU quota {q(p["cpu_max"])}; {p["meminfo"]}. Started {p["date"]}.','','## Grouped first stops','','Locations and root names are relative to src/compiler/. Only the first observation counts. Duplicate observations agree in all non-timing fields.','','| Roots | Location | Kind | Exact reason | Compared with c504dd8f | Root names |','| ---: | --- | --- | --- | --- | --- |']
for g in groups:
 names=', '.join(q(r)+(' ('+checks[r]['classification']+')' if r in checks else '') for r in g['roots'])
 lines.append(f'| {g["count"]} | {q(g["where"])} | {g["kind"]} | '+g['reason'].replace('|','\\|')+f' | '+(', '.join(str(g[k])+' '+k for k in ['unchanged','moved','new'] if g[k])+f' | {names} |'))
accepted=[r for g in groups if g['kind']=='accepted' for r in g['roots']]
lines+=['','The c504dd8f baseline had 73 roots stopped at tracing.ts:206:67. This run measures their actual next stops on the fetched main tip. The measured groups and exact per-root changes below show their next stops.','','## Roots lowering whole','',f'{len(accepted)}/79: '+', '.join(map(q,accepted))+'. Lower acceptance covers each complete resolved root program. Native output is not measured.','','## Comparison with c504dd8f','','Baseline: c504dd8f2d85b9e63b591f5d65baad44315f2ed2, from typescript/next-stops-c504dd8f. Its report and grouped data are retained in previous-REPORT.md and previous-grouped-first-stops.json. Unchanged means an identical (location, kind, exact reason) tuple for that root. Moved means a different tuple present in the baseline. New means a tuple absent from the baseline.','','| Current group | Roots | Unchanged | Moved | New |','| --- | ---: | ---: | ---: | ---: |']
for g in groups:
 c=collections.Counter(r['classification'] for r in comparison if r['root'] in g['roots'])
 lines.append(f'| {q(g["where"])} {g["kind"]} | {g["count"]} | {c["unchanged"]} | {c["moved"]} | {c["new"]} |')
c=collections.Counter(r['classification'] for r in comparison)
lines+=['',f'Total: {c["unchanged"]} unchanged, {c["moved"]} moved, {c["new"]} new. Exact before and after reasons are in comparison.json.','','| Root | Classification | Before location / kind | After location / kind |','| --- | --- | --- | --- |']
for r in comparison:lines.append(f'| {q(r["root"])} | {r["classification"]} | {q(r["before"][0])} {r["before"][1]} | {q(r["after"][0])} {r["after"][1]} |')
emitters={"optional property getPositionOfLineAndCharacter in SourceFileLike absent from structural source SourceFile, which can hide fields":"internal/lower/optional_widening.go:369 constructs the Refused reason (return at :368).","a checked view with a callable contract":"internal/lower/interface_cast.go:272 and internal/lower/view_contracts.go:57 emit this Refused reason.","a namespace value seen as an argument to a callee whose body can't be named":"internal/lower/namespace_value.go:362 constructs this reason and :380 selects it for an unnamed callee.","a primitive brand member _isResolvedConfigFileName whose type is not void":"internal/lower/phantom_brands.go:40 emits this Refused reason.", "a namespace object used as a value; no runtime container is emitted, so identity, receiver behavior, live export aliases and staged properties are not represented; use qualified members or named module imports":'internal/lower/namespaces.go:233 emits this NotYet reason.', "a cast the runtime can't check":'internal/lower/cast_proof.go:195 (castRefusal).', 'reading an enum before its runtime initialization; move the call after the enum declaration':'internal/lower/namespaces.go:284 and :335 emit this NotYet reason.', 'a namespace read before runtime initialization, directly or through a reachable call; move that read or call after the namespace declaration':'internal/lower/namespaces.go:286 and :338 emit this NotYet reason.'}
lines+=['','## Stop source and lowering emitters','']
for g in groups:
 if g['where']=='-':continue
 e=next(e for e in excerpts if e['where']==g['where'])
 lines += [f'### {g["where"]}','',g['kind']+': '+q(g['reason'])+'. '+emitters.get(g['reason'], 'See lowering-emitter-excerpts.txt for exact emitting lines.'),'','```ts',e['text'].rstrip(),'```','']
for name in ['tracing','sys']:
 findings=read(name+'-full-findings.json'); status=read(name+'-full-status.json')
 lines += ['## '+name+'.ts single-file full-mode census','', 'LATENT_FULL=1, LATENT_ASSERT_NO_OUTPUT=1, LATENT_ONLY_FILE set to the exact adapted src/compiler/'+name+'.ts path. The meter latent binary loaded the complete compiler directory. Child exit '+str(status['exit_code'])+'; elapsed '+format(status['seconds'],'.3f')+' seconds. Findings below are ordered by source filename, line and column; all kinds, phases, repeated findings and boundary records are retained. Locations in reachable callees are kept, even when outside the selected file.','', '| Phase | Kind | Location | Exact reason |','| --- | --- | --- | --- |']
 phases=collections.Counter(f.get('phase','') for f in findings); kinds=collections.Counter(f.get('kind','') for f in findings)
 lines.insert(len(lines)-3, str(len(findings))+' records: '+', '.join(str(v)+' '+k for k,v in phases.items())+'. Kinds: '+', '.join(str(v)+' '+k for k,v in kinds.items())+'. Refusal-scan findings: '+str(phases['refusal_scan'])+'.')
 for f in findings:
  lines.append('| '+f.get('phase','')+' | '+f.get('kind','')+' | '+q(f.get('where','').split('/src/compiler/')[-1])+' | '+f.get('reason','').replace('|','\\|').replace('\n','<br>')+' |')
 if any(f.get('phase') not in ('refusal_scan','lowering') for f in findings):
  lines += ['', 'Additional raw phases are retained exactly. The sys finding with phase deferred is included at its source location with the raw phase unchanged.']
 lines += ['']
lines+=['## Root-order evidence','',f'Classification: {art["status"]}. '+(art.get('stopping_reason') or 'The entry per-source ledger completed.'),'','The baseline report.py criteria require attempted-source and readiness-finding evidence from the entry run plus a Node throw. An incomplete entry ledger cannot establish an artifact. Independent stops remain counted. Node probes retain the existing 60-second TypeScript emit bound. Their actual exits and first errors are listed below; tool errors and timeouts do not establish Node throws.','','| Root | Independent stop | Node exit | First error | Label |','| --- | --- | ---: | --- | --- |']
for r in art['checks']:lines.append(f'| {q(r["root"])} | {q(r["where"])} | {r["node"]["exit"]} | {r["node"]["first_error"]} | {r["classification"]} |')
e=totals['guarded_entry'];s=e['child_status'];c=e['finding_totals'];o=totals['ordinary_counted_observations']['first_stop_totals']
lines+=['','## Latent totals','',f'Guarded entry: LATENT_FULL=1, LATENT_ASSERT_NO_OUTPUT=1, bound 1800 seconds. Child exit {s["exit_code"]}; elapsed {s["seconds"]:.3f} seconds; stopping reason {s["stopping_reason"] or "completed"}. Emitted findings: NotYet {c["NotYet"]}, Refused {c["Refused"]}, panics {c["panic"]}. Completed sources {e["completed_sources"]}/{e["expected_sources"]}; stream records {e["stream_records"]}; checker diagnostics {e["checker_diagnostics"]}.','',('Finished inside its bound.' if e['complete'] else 'Did not finish inside its bound. Totals cover emitted findings only. Unemitted findings are unknown, so these are not complete-program latent totals. Per-unit progress is recorded separately below.'),'',f'Ordinary census, 79 counted observations: NotYet {o["NotYet"]}, Refused {o["Refused"]}, panics {o["panic"]}, accepted {len(accepted)}. These are first-stop totals. The ordinary stream carries no latent counters, so ordinary full latent totals are unavailable.','','## Method, checkpoints and cleanup','','Read the c504dd8f method and scripts first and reused its recipe. Origin/main had advanced past 11f69c09 to 93e8aff5467b195ec93baf4b875f71bd0d86f378 when fetched. One adapted tree and an ordinary binary built from this SHA without an overlay. Sorted roots run sequentially in groups of 20, 20, 20 and 19. Each emits two observations (158 raw); only the first counts. run.py retains the prior per-root bounds and kills and reaps every child process group. Groups run directly in the foreground without the prior outer group timeout.','','Setup: source /workspace/adamic-tools/env.sh; bash cloud/setup.sh; npm ci --prefix stage3/api; export ADAMIC_TYPESCRIPT_SOURCE=/workspace/scratch/typescript-source. The source checkout HEAD is the pin above. apply-status.json and build-status.json identify the single apply and ordinary binary build.','','Guarded entry uses this SHA\'s stage3/census/latent/make_overlay.py and stage3/meter/entry_overlay.py, then go build with the resulting overlay. LATENT_ASSERT_NO_OUTPUT guards against usable IR output. The binaries follow stage3/meter/twice-daily.sh build_census: ordinary build, latent overlay, gofmt, entry overlay, gofmt, then separate entry and latent builds. The timing ledger uses LATENT_TIMES, as in the c504dd8f run and twice-daily.sh. Binary hashes, Go build metadata, adapted-source hashes and child status files identify measured bytes.','','A plain push to typescript/next-stops-11f69c09-checkpoint followed apply immediately, then each root group. checkpoint-push-*-status.json records each child exit. The final branch has one report-only commit directly on 93e8aff5467b195ec93baf4b875f71bd0d86f378. No force-push and no push to main.','','Every census child process group was killed and reaped, including after normal exits. validation.json records observation counts, duplicate agreement, source cleanliness and no surviving census processes. Files over 1 MB are gzip-compressed.']
t=totals['guarded_entry']['timing_progress']
lines += ['', '### Guarded entry timing progress','', str(t['records'])+' completed unit timing records across '+str(len(t['files']))+' source files. The source ledger count above is distinct from unit progress. Timing rows do not carry findings and cannot establish complete latent totals.','']
lines += ['The previous c504dd8f guarded entry pass reached 3163 completed unit timings within the same 1800-second bound. These are observed progress counts, not forecasts.', '']
if t['last_record']:
 lines += ['Last emitted timing record: '+q(t['last_record'].get('where','-').split('/src/compiler/')[-1])+'.','']
lines += ['| Source | Unit timing records |','| --- | ---: |']
for filename,count in t['files'].items():lines.append('| '+q(filename.split('/src/compiler/')[-1])+' | '+str(count)+' |')
text='\n'.join(lines)+'\n';assert '\u2014' not in text and '\u2013' not in text
(out/'REPORT.md').write_text(text)
